CREATE OR REPLACE FUNCTION mir_core.account_identity()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare uid uuid:=auth.uid();email text;confirmed timestamptz;begin
 if uid is null then raise exception 'Connexion requise' using errcode='42501',detail='AUTH_REQUIRED';end if;
 select u.email,u.email_confirmed_at into email,confirmed from auth.users u where u.id=uid;
 if email is null or confirmed is null then raise exception 'Confirmez votre adresse courriel avant de continuer' using errcode='42501',detail='EMAIL_UNCONFIRMED';end if;
 return jsonb_build_object('id',uid,'email',email);
end $function$

CREATE OR REPLACE FUNCTION mir_core.boutique_bend_price(spec jsonb, measures jsonb, metal text, fixed_cents bigint, tariff jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare topology jsonb:=coalesce(spec->'template',spec)->'topology'; segment jsonb; bend jsonb;
  width_in numeric:=0; side_in numeric; bend_count integer:=0; base_cents numeric:=fixed_cents; price bigint;
begin
  if topology->>'kind'='profile' then
    for segment in select value from jsonb_array_elements(topology->'segments') loop
      side_in:=mir_core.boutique_inches(measures->>(segment->>'label'));
      if side_in is null then raise exception 'Cote à compléter : %',segment->>'label' using errcode='22023'; end if;
      width_in:=width_in+side_in;
    end loop;
    for bend in select value from jsonb_array_elements(topology->'bends') loop
      if coalesce(bend->>'mode',bend->>'type')='hem'
        or (coalesce(bend->>'mode',bend->>'type')='signed' and (replace(bend->>'angle',',','.'))::numeric<>0)
        or (coalesce(bend->>'mode',bend->>'type')='interior' and (replace(bend->>'angle',',','.'))::numeric<>180) then
        bend_count:=bend_count+1;
      end if;
    end loop;
    base_cents:=coalesce(base_cents,width_in*120*(tariff->>'area_rate')::numeric*100+bend_count*(tariff->>'bend_cents')::integer);
  end if;
  if base_cents is null then return null; end if;
  price:=round(base_cents*(1+case when metal='aluminium' then (tariff->>'aluminum_basis_points')::numeric/10000 else 0 end));
  if price not between 1 and 10000000 then raise exception 'Montant de pliage hors limite' using errcode='22023'; end if;
  return price;
end $function$

CREATE OR REPLACE FUNCTION mir_core.boutique_delivery_km(address_id uuid, address jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare key text; distance numeric;
begin
  key:=md5(jsonb_build_array(address->>'line1',address->>'city',address->>'province',address->>'postalCode')::text);
  select d.distance_km into distance from mir_core.boutique_delivery_distances d
    where d.address_id=boutique_delivery_km.address_id and d.address_key=key
      and d.checked_at>now()-case when d.distance_km is null then interval '5 minutes' else interval '30 days' end;
  if found then return distance; end if;
  distance:=mir_core.boutique_geocode_km(address);
  insert into mir_core.boutique_delivery_distances as d(address_id,address_key,distance_km)
    values(address_id,key,distance)
    on conflict on constraint boutique_delivery_distances_pkey do update
      set address_key=excluded.address_key,distance_km=excluded.distance_km,checked_at=now();
  return distance;
end $function$

CREATE OR REPLACE FUNCTION mir_core.boutique_geocode_km(address jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare response jsonb; candidate jsonb; postal text; civic text; lat double precision; lng double precision;
begin
  postal:=upper(regexp_replace(address->>'postalCode','[^[:alnum:]]','','g'));
  civic:=substring(address->>'line1' from '^([0-9]+)[ ]');
  if postal is null or postal!~'^[A-Z][0-9][A-Z][0-9][A-Z][0-9]$' or civic is null
      or coalesce(lower(address->>'province'),'') not in ('qc','québec','quebec')
      or length(coalesce(address->>'line1',''))>200 or length(coalesce(address->>'city','')) not between 1 and 200
      or to_regprocedure('extensions.http_get(character varying,jsonb)') is null then return null; end if;

  -- Adresses Québec (MRNF, CC BY 4.0). Send the civic address only.
  select h.content::jsonb into response
  from extensions.http_get(
    'https://servicescarto.mrnf.gouv.qc.ca/pes/rest/services/Territoire/Adresse_Geocodage/GeocodeServer/findAddressCandidates',
    jsonb_build_object('SingleLine',concat_ws(', ',address->>'line1',address->>'city',postal),
      'f','json','outSR','4326','maxLocations','4','outFields','Addr_type')
  ) h where h.status=200;

  select a.value into candidate from jsonb_array_elements(response->'candidates') a
    where a.value->'attributes'->>'Addr_type'='Feature'
      and (a.value->>'score')::numeric>=92
      and substring(a.value->>'address' from '^([0-9]+)[ ]')=civic
      and right(upper(regexp_replace(a.value->>'address','[^[:alnum:]]','','g')),6)=postal
    order by (a.value->>'score')::numeric desc limit 1;
  lat:=(candidate->'location'->>'y')::double precision;
  lng:=(candidate->'location'->>'x')::double precision;
  if lat not between 43 and 63 or lng not between -81 and -56 then return null; end if;
  -- Haversine, origin verified at 1653, avenue des Affaires, Québec.
  return (2*6371*asin(sqrt(power(sin(radians(lat-46.865006094931)/2),2)
    +cos(radians(lat))*cos(radians(46.865006094931))*power(sin(radians(lng+71.420601906333)/2),2))))::numeric;
exception when others then
  -- A missing/ambiguous address or a provider outage requires a quote.
  return null;
end $function$

CREATE OR REPLACE FUNCTION mir_core.boutique_inches(value text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare normalized text; parts text[]; inches numeric; fraction text[];
begin
  if value is null or length(value)>64 then return null; end if;
  normalized:=lower(replace(value,',','.'));
  foreach fraction slice 1 in array array[
    ['¼','1/4'],['½','1/2'],['¾','3/4'],['⅛','1/8'],['⅜','3/8'],['⅝','5/8'],['⅞','7/8']
  ] loop
    normalized:=replace(normalized,fraction[1],' '||fraction[2]);
  end loop;
  normalized:=btrim(regexp_replace(regexp_replace(normalized,'[[:space:]]+',' ','g'),'[ ]*(po|in|["″])[ ]*$',''));
  normalized:=regexp_replace(normalized,'^\+ *','');
  if normalized ~ '^([0-9]+(\.[0-9]*)?|\.[0-9]+)$' then
    inches:=normalized::numeric;
  else
    parts:=regexp_match(normalized,'^(?:([0-9]+) )?([0-9]+)/([0-9]+)$');
    if parts is null or parts[3]::numeric=0 then return null; end if;
    inches:=coalesce(parts[1]::numeric,0)+parts[2]::numeric/parts[3]::numeric;
  end if;
  if inches>0 and inches*25.4<=100000 then return inches; end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION mir_core.coordination_guard_picking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare co mir_core.coordination_orders;max_pick numeric;begin
 select o.* into co from mir_core.coordination_orders o
 join mir_core.coordination_lines l on(l.organization_id,l.coordination_id)=(o.organization_id,o.id)
 where l.organization_id=new.organization_id and l.employee_line_id=new.order_line_id;
 if not found then return new;end if;
 if co.shipped_at is not null and new.delivered_qty>old.delivered_qty then
  raise exception 'Entrepôt déjà expédié : nouvelle demande requise' using errcode='40001';
 end if;
 select coalesce(sum(r.quantity),0) into max_pick from mir_core.coordination_routes r
 join mir_core.coordination_lines l on(l.organization_id,l.id)=(r.organization_id,r.coordination_line_id)
 where l.organization_id=new.organization_id and l.employee_line_id=new.order_line_id and r.route='warehouse';
 if new.delivered_qty>max_pick then
  raise exception 'Cette quantité ne fait pas partie du lot Entrepôt' using errcode='22023';
 end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION mir_core.coordination_replay(org uuid, request_id uuid, operation text, payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare found_op mir_core.coordination_ops;begin
 if request_id is null then raise exception 'Identifiant de requête requis' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(org::text||request_id::text,0));
 select * into found_op from mir_core.coordination_ops
 where organization_id=org and coordination_ops.request_id=coordination_replay.request_id;
 if found then
  if found_op.actor_id<>auth.uid() or found_op.op<>operation or found_op.signature is distinct from payload then
    raise exception 'Cette référence a déjà servi pour une action différente' using errcode='40001';
  end if;
  return found_op.result||jsonb_build_object('replayed',true);
 end if;
 return null;
end$function$

CREATE OR REPLACE FUNCTION mir_core.internal_object_allowed(object_name text, writing boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core', 'storage'
AS $function$declare parts text[];org uuid;scope text;entity uuid;owner uuid;r text;begin
 parts:=storage.foldername(object_name);if cardinality(parts)<>4 then return false;end if;begin org:=parts[1]::uuid;entity:=parts[3]::uuid;owner:=parts[4]::uuid;exception when others then return false;end;scope:=parts[2];
 if not exists(select 1 from mir_core.memberships where organization_id=org and user_id=auth.uid() and active and role in('admin','employee')) or(writing and owner<>auth.uid()) then return false;end if;r:=mir_core.staff_role(org);
 if scope='message' then return mir_core.conversation_allowed(org,entity);end if;if scope in('extra','issue','receipt','material','problem','report') then return mir_core.job_allowed(org,entity);end if;
 if scope='vehicle' then return r='admin' or exists(select 1 from mir_core.vehicles v where v.organization_id=org and v.id=entity and r in('boss','warehouse'));end if;
 if scope in('delivery','inspection','signature') then return exists(select 1 from mir_core.delivery_runs d where d.organization_id=org and d.id=entity and(r in('admin','boss','warehouse') or d.driver_id=auth.uid()));end if;return false;end$function$

CREATE OR REPLACE FUNCTION mir_core.publish_model(org uuid, model uuid, model_version integer, expected_revision integer, settings jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare current_revision integer; result integer; begin
 if not mir_core.has_role(org,array['admin']) then raise exception 'Admin requis' using errcode='42501';end if;
 if (settings->>'sale_length_in')::integer=144 and not exists(select 1 from mir_core.models where organization_id=org and id=model and name ilike 'J%soffite%') then raise exception 'Exception 12 pi réservée au J à soffite';end if;
 perform 1 from mir_core.models where organization_id=org and id=model for update;
 if not found then raise exception 'Modèle absent';end if;
 select revision into current_revision from mir_core.model_publications where organization_id=org and model_id=model;
 if coalesce(current_revision,0) is distinct from expected_revision then raise exception 'Conflit de révision' using errcode='40001';end if;
 insert into mir_core.model_publications(organization_id,model_id,version,sale_length_in,boutique,store,supplier_po,aluminum_cents,steel_cents,conditions,standard_measures,locked_measures,archived)
 values(org,model,model_version,coalesce((settings->>'sale_length_in')::integer,(select sale_length_in from mir_core.model_publications where organization_id=org and model_id=model),120),coalesce((settings->>'boutique')::boolean,false),coalesce((settings->>'store')::boolean,false),coalesce((settings->>'supplier_po')::boolean,false),(settings->>'aluminum_cents')::bigint,(settings->>'steel_cents')::bigint,coalesce(settings->>'conditions',''),coalesce(settings->'standard_measures','{}'),coalesce(settings->'locked_measures','{}'),coalesce((settings->>'archived')::boolean,false))
 on conflict(organization_id,model_id) do update set version=excluded.version,sale_length_in=excluded.sale_length_in,boutique=excluded.boutique,store=excluded.store,supplier_po=excluded.supplier_po,aluminum_cents=excluded.aluminum_cents,steel_cents=excluded.steel_cents,conditions=excluded.conditions,standard_measures=excluded.standard_measures,locked_measures=excluded.locked_measures,archived=excluded.archived,revision=mir_core.model_publications.revision+1
 returning revision into result;return result;
end $function$

CREATE OR REPLACE FUNCTION mir_core.queue_supplier_pdf(org uuid, po uuid, expected_revision integer, document uuid, request_id uuid, confirmed_recipient text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare o mir_core.orders; s mir_core.suppliers; d mir_core.documents; job mir_core.send_jobs; snapshot jsonb;
begin
  if not mir_core.has_role(org,array['admin']) then raise exception 'Admin actif requis' using errcode='42501'; end if;
  select * into o from mir_core.orders where organization_id=org and id=po for update;
  if not found or o.kind<>'supplier' or o.status<>'approved' or o.revision<>expected_revision then
    raise exception 'Bon approuvé et révision courante requis' using errcode='22023'; end if;
  select * into s from mir_core.suppliers where organization_id=org and id=o.supplier_id;
  if s.archived or s.verified_at is null or s.email is null or s.email !~ '^[^[:space:]<>@]+@[^[:space:]<>@]+\.[^[:space:]<>@]+$'
    or s.email is distinct from confirmed_recipient then raise exception 'Destinataire non confirmé' using errcode='22023'; end if;
  select * into d from mir_core.documents where organization_id=org and id=document and order_id=po and revision=expected_revision;
  if not found then raise exception 'PDF de la révision requis' using errcode='22023'; end if;
  select r.snapshot into snapshot from mir_core.order_revisions r where r.organization_id=org and r.order_id=po and r.revision=expected_revision;
  select * into job from mir_core.send_jobs where organization_id=org and idempotency_key=request_id;
  if found then
    if job.order_id<>po or job.revision<>expected_revision or job.document_id<>document or job.recipient<>confirmed_recipient then
      raise exception 'Identifiant déjà utilisé pour une autre demande' using errcode='22023'; end if;
    return job.id;
  end if;
  select * into job from mir_core.send_jobs where organization_id=org and order_id=po and revision=expected_revision and operation='purchase-order';
  if found then
    if job.document_id<>document or job.recipient<>confirmed_recipient then raise exception 'Révision déjà préparée avec un autre PDF/contact' using errcode='22023'; end if;
    return job.id;
  end if;
  insert into mir_core.send_jobs(organization_id,order_id,revision,document_id,operation,idempotency_key,recipient,approved_snapshot)
    values(org,po,expected_revision,document,'purchase-order',request_id,confirmed_recipient,snapshot) returning id into job.id;
  insert into mir_core.order_events(organization_id,order_id,event_type,details)
    values(org,po,'send-queued',jsonb_build_object('jobId',job.id,'revision',expected_revision));
  return job.id;
end $function$

CREATE OR REPLACE FUNCTION mir_core.stage_local_backup(org uuid, payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare entry jsonb; parsed jsonb; rows jsonb; record jsonb; k text; digest text; result uuid; begin
  if not mir_core.has_role(org,array['admin']) then raise exception 'Admin actif requis' using errcode='42501'; end if;
  if payload is null or payload->>'schema' is distinct from 'mir-local-backup-1' or jsonb_typeof(payload->'entries') is distinct from 'array'
    or jsonb_array_length(payload->'entries')=0 or octet_length(payload::text)>10485760 then
    raise exception 'Sauvegarde invalide' using errcode='22023';
  end if;
  for entry in select value from jsonb_array_elements(payload->'entries') loop
    k:=entry->>'key';
    if k is null or k not in ('mir_production_templates_v1','mir_production_requests_v1',
      'mir_production_admin_dossier_v1','mir_production_employee_dossier_v1',
      'mir_production_client_dossier_v1','mir_admin_procurement_v1','mir_production_admin_orders_v1')
      or jsonb_typeof(entry->'raw') is distinct from 'string' then
      raise exception 'Clé de sauvegarde interdite' using errcode='22023';
    end if;
    parsed:=(entry->>'raw')::jsonb;
    rows:=null;
    if k='mir_production_admin_orders_v1' then
      if jsonb_typeof(parsed) is distinct from 'array' then raise exception 'Archive invalide' using errcode='22023'; end if;
      rows:=parsed;
    elsif jsonb_typeof(parsed) is distinct from 'object' or parsed->>'version' is distinct from '1' then
      raise exception 'Version locale inconnue' using errcode='22023';
    elsif k='mir_production_templates_v1' then rows:=parsed->'records';
    elsif k='mir_production_requests_v1' then rows:=parsed->'requests';
    elsif k='mir_admin_procurement_v1' then
      rows:=parsed->'suppliers';
      if jsonb_typeof(rows) is distinct from 'array' or jsonb_typeof(parsed->'orders') is distinct from 'array' then
        raise exception 'Fournisseurs/bons invalides' using errcode='22023';
      end if;
      rows:=rows || (parsed->'orders');
    else rows:=parsed->'order'->'items';
    end if;
    if jsonb_typeof(rows) is distinct from 'array' then raise exception 'Liste locale absente' using errcode='22023'; end if;
    for record in select value from jsonb_array_elements(rows) loop
      if jsonb_typeof(record) is distinct from 'object' or jsonb_typeof(record->'id') is distinct from 'string'
        or length(record->>'id')=0 then raise exception 'Identifiant local invalide' using errcode='22023'; end if;
      if k='mir_production_templates_v1' and (jsonb_typeof(record->'versions') is distinct from 'array'
        or jsonb_array_length(record->'versions')=0) then raise exception 'Versions absentes' using errcode='22023'; end if;
    end loop;
    -- Suppliers and orders have separate identity spaces.
    if k='mir_admin_procurement_v1' then
      if (select count(*)<>count(distinct value->>'id') from jsonb_array_elements(parsed->'suppliers'))
        or (select count(*)<>count(distinct value->>'id') from jsonb_array_elements(parsed->'orders')) then
        raise exception 'Identifiant dupliqué' using errcode='22023'; end if;
    elsif (select count(*)<>count(distinct value->>'id') from jsonb_array_elements(rows)) then
      raise exception 'Identifiant dupliqué' using errcode='22023';
    end if;
  end loop;
  if (select count(*)<>count(distinct value->>'key') from jsonb_array_elements(payload->'entries')) then
    raise exception 'Clé dupliquée' using errcode='22023';
  end if;
  -- Sort by key; browser dates and entry order cannot defeat deduplication.
  select encode(sha256(convert_to(jsonb_agg(jsonb_build_object('key',value->>'key','raw',value->>'raw') order by value->>'key')::text,'UTF8')),'hex')
    into digest from jsonb_array_elements(payload->'entries');
  insert into mir_core.import_batches(organization_id,backup_sha256,backup)
    values(org,digest,payload) on conflict(organization_id,backup_sha256) do nothing;
  select id into result from mir_core.import_batches where organization_id=org and backup_sha256=digest;
  return result;
end $function$

CREATE OR REPLACE FUNCTION mir_core.validate_configuration_rules(rules jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare k text;v jsonb;begin
 if jsonb_typeof(rules) is distinct from 'object' or octet_length(rules::text)>32768 or rules-array['materials','colors','fixed_color','color_edit_roles','measure_edit_roles']<>'{}'::jsonb then raise exception 'Règles de configuration invalides' using errcode='22023';end if;
 foreach k in array array['materials','colors','color_edit_roles','measure_edit_roles'] loop
 if rules ? k then
 if jsonb_typeof(rules->k) is distinct from 'array' then raise exception 'Liste attendue : %',k using errcode='22023';end if;
 if jsonb_array_length(rules->k)>100 then raise exception 'Liste trop longue' using errcode='22023';end if;
 for v in select value from jsonb_array_elements(rules->k) loop
 if jsonb_typeof(v)<>'string' or length(btrim(v#>>'{}')) not between 1 and 200 then raise exception 'Valeur invalide' using errcode='22023';end if;
 if k='materials' and v#>>'{}' not in ('aluminium','acier') then raise exception 'Métal inconnu' using errcode='22023';end if;
 if k in ('color_edit_roles','measure_edit_roles') and v#>>'{}' not in ('client','employee') then raise exception 'Rôle inconnu' using errcode='22023';end if;
 end loop;
 end if;end loop;
 if rules ? 'materials' and jsonb_array_length(rules->'materials')=0 then raise exception 'Au moins un métal requis' using errcode='22023';end if;
 if rules ? 'color_edit_roles' and not(rules->'color_edit_roles' @> '["client","employee"]'::jsonb) then
 if jsonb_typeof(rules->'fixed_color') is distinct from 'string' or length(btrim(rules->>'fixed_color')) not between 1 and 200 then raise exception 'Couleur fixe requise pour les rôles verrouillés' using errcode='22023';end if;
 end if;
 if rules ? 'fixed_color' and (jsonb_typeof(rules->'fixed_color') is distinct from 'string' or length(btrim(rules->>'fixed_color')) not between 1 and 200 or (jsonb_array_length(coalesce(rules->'colors','[]'))>0 and not(rules->'colors' @> jsonb_build_array(rules->>'fixed_color')))) then raise exception 'Couleur fixe non autorisée' using errcode='22023';end if;
end $function$

CREATE OR REPLACE FUNCTION mir_core.warehouse_auto_link_line()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare candidate text;matched uuid;kind text;begin
 select o.kind into kind from mir_core.orders o
 where o.organization_id=new.organization_id and o.id=new.order_id;
 if kind is distinct from 'employee' then return new;end if;
 candidate:=coalesce(new.specification->>'stockKey',new.specification->>'inventoryKey');
 if candidate is null then return new;end if;
 select s.id into matched from mir_core.warehouse_skus s
 where s.organization_id=new.organization_id and s.source_ref=candidate
 and s.source_kind=case when new.model_id is null then 'hardware' else 'bending' end
 and not s.archived;
 if matched is not null then
  insert into mir_core.warehouse_fulfillment(organization_id,order_line_id,sku_id)
  values(new.organization_id,new.id,matched) on conflict do nothing;
 end if;
 return new;
end$function$

CREATE OR REPLACE FUNCTION public.mir_account_create_invitation(p_email text, p_job_ids uuid[] DEFAULT '{}'::uuid[], p_request_id uuid DEFAULT gen_random_uuid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare identity jsonb;cfg mir_core.account_settings;uid uuid;token text;created mir_core.account_invitations;email text:=lower(trim(p_email));begin
 identity:=mir_core.account_identity();uid:=(identity->>'id')::uuid;select * into cfg from mir_core.account_settings where singleton;
 if not mir_core.has_role(cfg.organization_id,array['admin']) then raise exception 'Droits administrateur requis' using errcode='42501';end if;
 if email is null or length(email)>254 or email!~'^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' or coalesce(cardinality(p_job_ids),0)>100 then raise exception 'Courriel ou chantiers invalides' using errcode='22023';end if;
 if exists(select 1 from unnest(p_job_ids) j where not exists(select 1 from mir_core.jobs x where x.organization_id=cfg.organization_id and x.id=j and not x.archived)) then raise exception 'Chantier non autorisé' using errcode='42501';end if;
 select * into created from mir_core.account_invitations where organization_id=cfg.organization_id and request_id=p_request_id;
 if found then return jsonb_build_object('id',created.id,'status','prepared','alreadyCreated',true,'activationPath',null);end if;
 token:=rtrim(translate(encode(decode(replace(gen_random_uuid()::text||gen_random_uuid()::text,'-',''),'hex'),'base64'),'+/','-_'),'=');
 insert into mir_core.account_invitations(organization_id,email,token_hash,job_ids,request_id,created_by) values(cfg.organization_id,email,encode(sha256(convert_to(token,'UTF8')),'hex'),coalesce(p_job_ids,'{}'),p_request_id,uid) returning * into created;
 return jsonb_build_object('id',created.id,'status','prepared','expiresAt',created.expires_at,'activationPath','chantier.html?invitation='||token,'delivery','manual');
end $function$

CREATE OR REPLACE FUNCTION public.mir_account_import_signup_address()
 RETURNS uuid
