CREATE OR REPLACE FUNCTION public.mir_account_save_address(p_address jsonb, p_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare identity jsonb;uid uuid;clean jsonb:='{}';key text;value text;address_id uuid:=coalesce(p_id,gen_random_uuid());begin
 identity:=mir_core.account_identity();uid:=(identity->>'id')::uuid;
 if jsonb_typeof(p_address)<>'object' or octet_length(p_address::text)>6000 then raise exception 'Adresse invalide' using errcode='22023';end if;
 foreach key in array array['label','recipient','line1','line2','city','province','postalCode','country'] loop
  value:=trim(coalesce(p_address->>key,''));
  if length(value)>200 then raise exception 'Un champ de l’adresse est trop long' using errcode='22023';end if;
  if key=any(array['recipient','line1','city','province','postalCode','country']) and value='' then raise exception 'Complétez les champs de livraison obligatoires' using errcode='22023';end if;
  clean:=clean||jsonb_build_object(key,value);
 end loop;
 if p_id is not null and not exists(select 1 from mir_core.customer_addresses a where a.id=p_id and a.user_id=uid) then raise exception 'Cette adresse ne vous appartient pas' using errcode='42501';end if;
 insert into mir_core.customer_addresses(id,user_id,address) values(address_id,uid,clean)
 on conflict(id) do update set address=excluded.address,updated_at=now() where customer_addresses.user_id=uid;
 if not found then raise exception 'Cette adresse ne vous appartient pas' using errcode='42501';end if;return address_id;
end $function$

CREATE OR REPLACE FUNCTION public.mir_account_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare identity jsonb;cfg mir_core.account_settings;uid uuid;actor_role text;orders jsonb;addresses jsonb;begin
 identity:=mir_core.account_identity();uid:=(identity->>'id')::uuid;
 select * into cfg from mir_core.account_settings where singleton;
 if cfg.organization_id is null then raise exception 'Le compte MIR attend sa configuration serveur' using errcode='42501',detail='ACCOUNT_NOT_CONFIGURED';end if;
 select m.role into actor_role from mir_core.memberships m where m.organization_id=cfg.organization_id and m.user_id=uid and m.active;
 if actor_role is null then
  if exists(select 1 from mir_core.memberships m where m.organization_id=cfg.organization_id and m.user_id=uid) or not cfg.allow_client_signup then
   raise exception 'Votre accès doit être confirmé par MIR' using errcode='42501',detail='ACCESS_DENIED';end if;
  -- The public caller supplies neither a role nor an organization. Never reactivate an inactive member.
  insert into mir_core.memberships(organization_id,user_id,role,active) values(cfg.organization_id,uid,'client',true) on conflict do nothing;
  select m.role into actor_role from mir_core.memberships m where m.organization_id=cfg.organization_id and m.user_id=uid and m.active;
 end if;
 if actor_role is null then raise exception 'Accès MIR inactif' using errcode='42501';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',o.id,'status',o.status,'createdAt',o.created_at,'revision',o.revision,
 'events',coalesce((select jsonb_agg(jsonb_build_object('createdAt',e.created_at,'label',case e.event_type when 'request-submitted' then 'Demande reçue' when 'delivered' then 'Livrée' when 'shipped' then 'Expédiée' else 'Statut mis à jour' end) order by e.created_at)
 from mir_core.order_events e where e.organization_id=o.organization_id and e.order_id=o.id),'[]')) order by o.created_at desc),'[]') into orders
 from mir_core.orders o where o.organization_id=cfg.organization_id and o.kind='client' and o.owner_id=uid;
 select coalesce(jsonb_agg(a.address||jsonb_build_object('id',a.id) order by a.created_at),'[]') into addresses from mir_core.customer_addresses a where a.user_id=uid;
 return jsonb_build_object('userId',uid,'email',identity->>'email','role',actor_role,'organizationId',cfg.organization_id,'orders',orders,'addresses',addresses,
 'capabilities',jsonb_build_object('customerCheckout',false,'payment',false));
end $function$

CREATE OR REPLACE FUNCTION public.mir_add_master_version(org uuid, model uuid, expected_revision integer, template jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare v integer;p mir_core.model_publications;begin
 if not mir_core.has_role(org,array['admin']) then raise exception 'Admin requis' using errcode='42501';end if;
 perform 1 from mir_core.models where organization_id=org and id=model for update;
 select * into p from mir_core.model_publications where organization_id=org and model_id=model;
 if not found or p.revision<>expected_revision then raise exception 'Conflit de révision' using errcode='40001';end if;
 if template->>'schema' is distinct from 'mir-production-template-1' or jsonb_typeof(template->'fields') is distinct from 'array' then raise exception 'Géométrie inconnue';end if;
 select max(version)+1 into v from mir_core.model_versions where organization_id=org and model_id=model;
 if (template->>'version')::integer is distinct from v then raise exception 'Numéro de version suivant requis';end if;
 insert into mir_core.model_versions(organization_id,model_id,version,specification) values(org,model,v,(select specification-'template' from mir_core.model_versions where organization_id=org and model_id=model and version=p.version)||jsonb_build_object('template',template));
 update mir_core.model_publications set version=v,revision=revision+1,boutique=false,store=false,supplier_po=false where organization_id=org and model_id=model;
 return p.revision+1;
end $function$

CREATE OR REPLACE FUNCTION public.mir_admin_logistics_action(org uuid, action text, entity uuid, payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$declare v uuid;token uuid;rule uuid;begin
 if mir_core.staff_role(org)<>'admin' or jsonb_typeof(payload)<>'object' then raise exception 'Admin requis' using errcode='42501';end if;
 if action='vehicle_save' then
  if entity is null then insert into mir_core.vehicles(organization_id,internal_number,name,vehicle_type,make,model,model_year,plate,vin,capacity_kg,status,notes) values(org,btrim(payload->>'internalNumber'),btrim(payload->>'name'),payload->>'type',coalesce(payload->>'make',''),coalesce(payload->>'model',''),nullif(payload->>'year','')::int,coalesce(payload->>'plate',''),coalesce(payload->>'vin',''),nullif(payload->>'capacityKg','')::numeric,coalesce(payload->>'status','available'),coalesce(payload->>'notes','')) returning id into v;
  else update mir_core.vehicles set name=coalesce(nullif(btrim(payload->>'name'),''),name),status=coalesce(nullif(payload->>'status',''),status),notes=coalesce(payload->>'notes',notes),updated_at=now() where organization_id=org and id=entity returning id into v;end if;
  insert into mir_core.inventory_locations(organization_id,location_type,name,vehicle_id) select org,case when vehicle_type='trailer' then 'trailer' else 'vehicle' end,name,id from mir_core.vehicles where organization_id=org and id=v on conflict do nothing;
 elsif action='qr_regenerate' then update mir_core.vehicle_qr_tokens set active=false,disabled_at=now() where organization_id=org and vehicle_id=entity and active;token:=gen_random_uuid();insert into mir_core.vehicle_qr_tokens(organization_id,vehicle_id,token_hash,created_by) values(org,entity,md5(token::text),auth.uid());v:=entity;
 elsif action='qr_disable' then update mir_core.vehicle_qr_tokens set active=false,disabled_at=now() where organization_id=org and vehicle_id=entity and active;v:=entity;
 elsif action='assign' then insert into mir_core.vehicle_authorizations(organization_id,vehicle_id,employee_id,kind,starts_at,ends_at,approved_by,reason) values(org,entity,(payload->>'employeeId')::uuid,payload->>'kind',coalesce(nullif(payload->>'startsAt','')::timestamptz,now()),nullif(payload->>'endsAt','')::timestamptz,auth.uid(),coalesce(payload->>'reason',''));v:=entity;
 elsif action='rule_save' then rule:=coalesce(entity,gen_random_uuid());insert into mir_core.inspection_rules(organization_id,id,phase,code,label,requirement,vehicle_type,vehicle_id,trailer_only,position,photo_required,comment_required,failure_blocks,approver_role) values(org,rule,payload->>'phase',payload->>'code',payload->>'label',payload->>'requirement',nullif(payload->>'vehicleType',''),nullif(payload->>'vehicleId','')::uuid,coalesce((payload->>'trailerOnly')::boolean,false),coalesce((payload->>'position')::int,0),coalesce((payload->>'photoRequired')::boolean,false),coalesce((payload->>'commentRequired')::boolean,false),coalesce((payload->>'failureBlocks')::boolean,false),coalesce(payload->>'approverRole','boss_admin')) on conflict(organization_id,id) do update set label=excluded.label,requirement=excluded.requirement,vehicle_type=excluded.vehicle_type,vehicle_id=excluded.vehicle_id,trailer_only=excluded.trailer_only,position=excluded.position,photo_required=excluded.photo_required,comment_required=excluded.comment_required,failure_blocks=excluded.failure_blocks,approver_role=excluded.approver_role;v:=rule;
 elsif action='maintenance_save' then insert into mir_core.vehicle_maintenance(organization_id,vehicle_id,kind,performed_at,due_date,due_odometer,alert_enabled,alert_days,odometer,notes,document_path,created_by) values(org,entity,payload->>'kind',nullif(payload->>'performedAt','')::date,nullif(payload->>'dueDate','')::date,nullif(payload->>'dueOdometer','')::numeric,coalesce((payload->>'alertEnabled')::boolean,true),coalesce((payload->>'alertDays')::int,30),nullif(payload->>'odometer','')::numeric,coalesce(payload->>'notes',''),nullif(payload->>'documentPath',''),auth.uid()) returning id into v;
 else raise exception 'Action admin inconnue' using errcode='22023';end if;
 insert into mir_core.logistics_audit(organization_id,actor_id,action,entity_type,entity_id,details) values(org,auth.uid(),action,'logistics',v,payload);
 return jsonb_build_object('id',v,'qrToken',token);
end$function$

CREATE OR REPLACE FUNCTION public.mir_admin_publish_model(org uuid, model uuid, expected_revision integer, settings jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare ver integer;new_revision integer;begin
 if not mir_core.has_role(org,array['admin']) then raise exception 'Admin requis' using errcode='42501';end if;
 if jsonb_typeof(settings->'standard_measures') is distinct from 'object' or jsonb_typeof(settings->'locked_measures') is distinct from 'object' then raise exception 'Mesures invalides';end if;
 perform 1 from mir_core.models where organization_id=org and id=model for update;
 select version into ver from mir_core.model_publications where organization_id=org and model_id=model;
 if settings ? 'sale_length_in' then
 if (settings->>'sale_length_in')::integer=144 and not exists(select 1 from mir_core.models where organization_id=org and id=model and name ilike 'J%soffite%') then raise exception 'Exception 12 pi réservée au J à soffite';end if;
 update mir_core.model_publications set sale_length_in=(settings->>'sale_length_in')::integer,aluminum_cents=(settings->>'aluminum_cents')::bigint,steel_cents=(settings->>'steel_cents')::bigint where organization_id=org and model_id=model;
 end if;
 if settings ? 'configuration_rules' then
 perform mir_core.validate_configuration_rules(settings->'configuration_rules');
 update mir_core.model_publications set configuration_rules=settings->'configuration_rules' where organization_id=org and model_id=model;
 end if;
 new_revision:=mir_core.publish_model(org,model,ver,expected_revision,settings);
 return new_revision;
end $function$

CREATE OR REPLACE FUNCTION public.mir_admin_save_bend_tariff(org uuid, expected_revision integer, settings jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare current_tariff jsonb; rate numeric; result jsonb;
begin
  if not mir_core.has_role(org,array['admin']) then raise exception 'Admin requis' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('boutique-bend-tariff:'||org::text,0));
  current_tariff:=mir_core.boutique_bend_tariff(org);
  if (current_tariff->>'revision')::integer is distinct from expected_revision then
    raise exception 'Tarifs modifiés. Actualisez avant de réessayer.' using errcode='40001';
  end if;
  rate:=(settings->>'area_rate')::numeric;
  if rate is null or rate<>round(rate,6) then
    raise exception 'Tarif au pouce carré invalide' using errcode='22023';
  end if;
  insert into mir_core.boutique_bend_tariffs as t
    (organization_id,area_rate,bend_cents,aluminum_basis_points,delivery_cents,revision)
  values (org,rate,(settings->>'bend_cents')::integer,(settings->>'aluminum_basis_points')::integer,
    (settings->>'delivery_cents')::integer,expected_revision+1)
  on conflict (organization_id) do update
    set area_rate=excluded.area_rate,bend_cents=excluded.bend_cents,
        aluminum_basis_points=excluded.aluminum_basis_points,delivery_cents=excluded.delivery_cents,
        revision=excluded.revision
  returning to_jsonb(t)-'organization_id' into result;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.mir_assign_job(org uuid, job_name text, employee uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare jid uuid;begin
 if not mir_core.has_role(org,array['admin']) then raise exception 'Admin requis' using errcode='42501';end if;
 if length(btrim(job_name)) not between 1 and 200 or not exists(select 1 from mir_core.memberships where organization_id=org and user_id=employee and role='employee' and active) then raise exception 'Chantier ou employé invalide';end if;
 insert into mir_core.jobs(organization_id,name) values(org,btrim(job_name)) on conflict(organization_id,name) do update set name=excluded.name returning id into jid;
