CREATE OR REPLACE FUNCTION public.mir_coordination_add(org uuid, coord_id uuid, existing_coord_line uuid, additional_qty numeric, expected_revision integer, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare o mir_core.coordination_orders;original mir_core.coordination_lines;
 src mir_core.order_lines;new_source uuid;new_line uuid;new_revision integer;prior jsonb;payload jsonb;result jsonb;begin
 if not mir_core.coordination_allowed(org) then raise exception 'Adjointe MIR requise' using errcode='42501';end if;
 payload:=jsonb_build_object('coordId',coord_id,'lineId',existing_coord_line,'additional',additional_qty,'expectedRevision',expected_revision);
 prior:=mir_core.coordination_replay(org,request_id,'add',payload);if prior is not null then return prior;end if;
 select * into o from mir_core.coordination_orders where organization_id=org and id=coord_id for update;
 if not found or o.shipped_at is not null then raise exception 'Commande déjà expédiée ou inconnue' using errcode='40001';end if;
 if o.revision<>expected_revision then raise exception 'Commande modifiée : actualiser avant ajout' using errcode='40001';end if;
 select * into original from mir_core.coordination_lines
 where organization_id=org and id=existing_coord_line and coordination_id=coord_id;
 if not found then raise exception 'Article inexistant dans cette commande' using errcode='22023';end if;
 if additional_qty is null or additional_qty<=0 or additional_qty>100000 or scale(additional_qty)>3
 then raise exception 'Quantité supplémentaire invalide' using errcode='22023';end if;
 select * into src from mir_core.order_lines where organization_id=org and id=original.employee_line_id;
 if not found or src.order_id<>o.employee_order_id then raise exception 'Source de l article introuvable' using errcode='22023';end if;
 insert into mir_core.order_lines(organization_id,order_id,revision,quantity,unit,specification,model_id,model_version)
 values(org,src.order_id,src.revision,additional_qty,src.unit,
  jsonb_set(src.specification,'{quantity}',to_jsonb(additional_qty),true)||jsonb_build_object('coordinationExtra',true),
  src.model_id,src.model_version) returning id into new_source;
 insert into mir_core.coordination_lines(organization_id,coordination_id,employee_line_id,origin,
  requested_qty,item_name,unit,variant_key,specification,added_by)
 values(org,o.id,new_source,'added',additional_qty,original.item_name,original.unit,
  original.variant_key,src.specification,auth.uid()) returning id into new_line;
 new_revision:=o.revision+1;
 update mir_core.coordination_orders set revision=new_revision,updated_at=now()
 where organization_id=org and id=o.id;
 insert into mir_core.coordination_events(organization_id,coordination_id,revision,event_type,payload,actor_id)
 values(org,o.id,new_revision,'quantity_added',
 jsonb_build_object('lineId',new_line,'sourceLineId',original.id,'sku',original.variant_key,
 'name',original.item_name,'unit',original.unit,'delta',additional_qty),auth.uid());
 result:=jsonb_build_object('revision',new_revision,'newLineId',new_line,
  'message','+'||additional_qty||' '||original.unit||' '||original.item_name);
 return mir_core.coordination_receipt(org,request_id,'add',payload,result);
end$function$

CREATE OR REPLACE FUNCTION public.mir_coordination_metadata(org uuid, coord_id uuid, expected_revision integer, vals jsonb, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare o mir_core.coordination_orders;payload jsonb;prior jsonb;result jsonb;rev integer;
 v_job text;v_address text;v_team text;v_priority text;v_notes text;begin
 if not mir_core.coordination_allowed(org) then raise exception 'Adjointe MIR requise' using errcode='42501';end if;
 if jsonb_typeof(vals) is distinct from 'object' or vals-array['job','address','team','priority','notes']<>'{}'::jsonb then
 raise exception 'Métadonnées non autorisées' using errcode='22023';end if;
 payload:=jsonb_build_object('coord',coord_id,'revision',expected_revision,'values',vals);
 prior:=mir_core.coordination_replay(org,request_id,'metadata',payload);if prior is not null then return prior;end if;
 select * into o from mir_core.coordination_orders where organization_id=org and id=coord_id for update;
 if not found or o.shipped_at is not null then raise exception 'Commande inconnue ou déjà expédiée' using errcode='40001';end if;
 if o.revision<>expected_revision then raise exception 'Commande modifiée : actualiser' using errcode='40001';end if;
 v_job:=btrim(coalesce(vals->>'job',o.job));v_address:=btrim(coalesce(vals->>'address',o.delivery_address));
 v_team:=btrim(coalesce(vals->>'team',o.team));v_priority:=coalesce(vals->>'priority',o.priority);
 v_notes:=btrim(coalesce(vals->>'notes',o.notes));
 if length(v_job)>200 or length(v_address)>360 or length(v_team)>200 or length(v_notes)>800 or v_priority not in ('normal','urgent')
 then raise exception 'Chantier, livraison ou priorité invalide' using errcode='22023';end if;
 rev:=o.revision+1;
 update mir_core.coordination_orders set job=v_job,delivery_address=v_address,team=v_team,
 priority=v_priority,notes=v_notes,revision=rev,updated_at=now()
 where organization_id=org and id=o.id;
 insert into mir_core.coordination_events(organization_id,coordination_id,revision,event_type,payload,actor_id)
 values(org,o.id,rev,'note_changed',jsonb_build_object('job',v_job,'address',v_address,'team',v_team,'priority',v_priority),auth.uid());
 result:=jsonb_build_object('id',o.id,'revision',rev);
 return mir_core.coordination_receipt(org,request_id,'metadata',payload,result);
end$function$

CREATE OR REPLACE FUNCTION public.mir_coordination_open(org uuid, source_order uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare o mir_core.orders;co mir_core.coordination_orders;src jsonb;count_lines integer;begin
 if not mir_core.coordination_allowed(org) then raise exception 'Coordination non autorisée' using errcode='42501';end if;
 select * into o from mir_core.orders where organization_id=org and id=source_order for update;
 if not found or o.kind<>'employee' or o.status='cancelled' then raise exception 'Commande employé introuvable' using errcode='22023';end if;
 select count(*) into count_lines from mir_core.order_lines where organization_id=org and order_id=source_order;
 if count_lines=0 then raise exception 'Commande sans lignes serveur : importer/valider la demande avant triage' using errcode='22023';end if;
 select snapshot into src from mir_core.order_revisions
 where organization_id=org and order_id=source_order and revision=o.revision;
 insert into mir_core.coordination_orders(organization_id,employee_order_id,created_by,job,delivery_address,team,notes)
 values(org,source_order,auth.uid(),coalesce(src->'configuration'->>'chantier',src->>'job',''),
 coalesce(src->>'address',src->>'shipTo',''),coalesce(src->>'team',''),coalesce(src->>'note',''))
 on conflict(organization_id,employee_order_id) do nothing;
 select * into co from mir_core.coordination_orders
 where organization_id=org and employee_order_id=source_order for update;
 insert into mir_core.coordination_lines(organization_id,coordination_id,employee_line_id,origin,requested_qty,
 item_name,unit,variant_key,specification)
 select org,co.id,ol.id,'original',ol.quantity,
 coalesce(ol.specification->>'name',ol.specification->>'itemName','Référence à identifier'),
 ol.unit,coalesce(ol.specification->>'stockKey',ol.specification->>'inventoryKey',''),
 ol.specification from mir_core.order_lines ol
 where ol.organization_id=org and ol.order_id=source_order
 on conflict(organization_id,employee_line_id) do nothing;
 insert into mir_core.coordination_events(organization_id,coordination_id,revision,event_type,actor_id)
 values(org,co.id,1,'received',auth.uid()) on conflict(organization_id,coordination_id,revision) do nothing;
 return jsonb_build_object('id',co.id,'revision',co.revision,'sourceOrderId',source_order);
end$function$

CREATE OR REPLACE FUNCTION public.mir_coordination_route(org uuid, coord_id uuid, coord_line uuid, warehouse_qty numeric, suppliers jsonb, expected_revision integer, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare o mir_core.coordination_orders;l mir_core.coordination_lines;
 item jsonb; vendor uuid; q numeric; total numeric; prior jsonb;result jsonb;revision_next integer;
 old_routes integer; old_matched integer; picked numeric;payload jsonb;
begin
 if not mir_core.coordination_allowed(org) then raise exception 'Adjointe MIR requise' using errcode='42501';end if;
 payload:=jsonb_build_object('coordId',coord_id,'lineId',coord_line,'warehouseQty',warehouse_qty,
  'suppliers',suppliers,'expectedRevision',expected_revision);
 prior:=mir_core.coordination_replay(org,request_id,'route',payload);if prior is not null then return prior;end if;
 select * into o from mir_core.coordination_orders where organization_id=org and id=coord_id for update;
 if not found or o.shipped_at is not null then raise exception 'Commande expédiée ou inconnue' using errcode='40001';end if;
 if o.revision<>expected_revision then raise exception 'Commande modifiée : actualiser avant de répartir' using errcode='40001';end if;
 select * into l from mir_core.coordination_lines where organization_id=org and id=coord_line and coordination_id=o.id;
 if not found then raise exception 'Ligne inconnue' using errcode='22023';end if;
 if warehouse_qty is null or warehouse_qty<0 or warehouse_qty>l.requested_qty or scale(warehouse_qty)>3
 or jsonb_typeof(suppliers) is distinct from 'array' or jsonb_array_length(suppliers)>20
 then raise exception 'Répartition invalide' using errcode='22023';end if;
 select coalesce(f.delivered_qty,0) into picked from mir_core.warehouse_fulfillment f
 where f.organization_id=org and f.order_line_id=l.employee_line_id;
 if warehouse_qty<coalesce(picked,0) then raise exception 'Des pièces sont déjà scannées et sorties du stock' using errcode='22023';end if;
 if warehouse_qty>0 and not exists(
  select 1 from mir_core.warehouse_fulfillment f
  join mir_core.warehouse_skus s on(s.organization_id,s.id)=(f.organization_id,f.sku_id)
  where f.organization_id=org and f.order_line_id=l.employee_line_id
   and not s.archived and s.source_ref=l.variant_key
 ) then raise exception 'Lier la référence exacte au QR Entrepôt avant de répartir' using errcode='22023';end if;
 -- Un bon déjà créé ou une réception ne peut pas être effacé par changement de radio.
 if exists(select 1 from mir_core.coordination_routes r where r.organization_id=org
  and r.coordination_line_id=l.id and(r.supplier_order_id is not null or r.received_qty>0))
 then raise exception 'Bon fournisseur lié : créer une révision ou un complément; ne pas écraser les lignes' using errcode='40001';end if;
 total:=warehouse_qty;
 for item in select value from jsonb_array_elements(suppliers) loop
   if jsonb_typeof(item) is distinct from 'object' or item->>'supplierId' is null
    or item->>'quantity' is null then raise exception 'Fournisseur ou quantité manquante' using errcode='22023';end if;
   begin vendor:=(item->>'supplierId')::uuid;q:=(item->>'quantity')::numeric;
   exception when others then raise exception 'Référence fournisseur ou quantité invalide' using errcode='22023';end;
   if q<=0 or scale(q)>3 or q>l.requested_qty or not exists(
    select 1 from mir_core.suppliers s where s.organization_id=org and s.id=vendor and not s.archived
   ) then raise exception 'Fournisseur introuvable ou quantité hors limites' using errcode='22023';end if;
   total:=total+q;
 end loop;
 if total>l.requested_qty then raise exception 'Entrepôt + fournisseurs dépasse les quantités demandées' using errcode='22023';end if;
 delete from mir_core.coordination_routes where organization_id=org and coordination_line_id=l.id;
 if warehouse_qty>0 then insert into mir_core.coordination_routes(organization_id,coordination_line_id,route,quantity)
 values(org,l.id,'warehouse',warehouse_qty);end if;
 for item in select value from jsonb_array_elements(suppliers) loop
  insert into mir_core.coordination_routes(organization_id,coordination_line_id,route,quantity,supplier_id,notes)
  values(org,l.id,'supplier',(item->>'quantity')::numeric,(item->>'supplierId')::uuid,
   left(coalesce(item->>'note',''),500));
 end loop;
 revision_next:=o.revision+1;
 update mir_core.coordination_orders set revision=revision_next,updated_at=now() where organization_id=org and id=o.id;
 insert into mir_core.coordination_events(organization_id,coordination_id,revision,event_type,payload,actor_id)
 values(org,o.id,revision_next,'routed',jsonb_build_object('lineId',l.id,'name',l.item_name,
  'warehouse',warehouse_qty,'suppliers',suppliers,'unassigned',l.requested_qty-total),auth.uid());
 result:=jsonb_build_object('revision',revision_next,'lineId',l.id,'warehouse',warehouse_qty,'unassigned',l.requested_qty-total);
 return mir_core.coordination_receipt(org,request_id,'route',payload,result);
end$function$

CREATE OR REPLACE FUNCTION public.mir_coordination_ship(org uuid, coord_id uuid, expected_revision integer, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare o mir_core.coordination_orders;line record;num int;unread integer;
 payload jsonb;prior jsonb;result jsonb;new_revision integer;
begin
 if not mir_core.warehouse_allowed(org) then raise exception 'Entrepôt autorisé requis' using errcode='42501';end if;
 payload:=jsonb_build_object('coordId',coord_id,'expectedRevision',expected_revision);
 prior:=mir_core.coordination_replay(org,request_id,'ship',payload);if prior is not null then return prior;end if;
 select * into o from mir_core.coordination_orders where organization_id=org and id=coord_id for update;
 if not found or o.shipped_at is not null then raise exception 'Commande déjà expédiée ou introuvable' using errcode='40001';end if;
 if o.revision<>expected_revision then raise exception 'La commande a changé : actualiser avant expédition' using errcode='40001';end if;
 select coalesce(max(e.revision),0) into unread from mir_core.coordination_events e
 where e.organization_id=org and e.coordination_id=o.id
 and e.event_type in ('received','routed','quantity_added','note_changed');
 if not exists(select 1 from mir_core.coordination_acks a
 where a.organization_id=org and a.coordination_id=o.id
 and a.user_id=auth.uid() and a.seen_revision>=unread)
 then raise exception 'Lire et confirmer les modifications avant expédition' using errcode='42501';end if;
 select count(*) into num from mir_core.coordination_routes r
 join mir_core.coordination_lines l on(l.organization_id,l.id)=(r.organization_id,r.coordination_line_id)
 where l.organization_id=org and l.coordination_id=o.id and r.route='warehouse';
 if num=0 then raise exception 'Aucun article affecté à l Entrepôt' using errcode='22023';end if;
 for line in select l.item_name,r.quantity,coalesce(f.delivered_qty,0) as picked
  from mir_core.coordination_routes r
  join mir_core.coordination_lines l on(l.organization_id,l.id)=(r.organization_id,r.coordination_line_id)
  left join mir_core.warehouse_fulfillment f on(f.organization_id,f.order_line_id)=(l.organization_id,l.employee_line_id)
  where l.organization_id=org and l.coordination_id=o.id and r.route='warehouse'
 loop
  if line.picked<>line.quantity then
   raise exception 'Préparation incomplète : % (préparé %, demandé %)',
    line.item_name,line.picked,line.quantity using errcode='22023';
  end if;
 end loop;
 select coalesce(jsonb_agg(jsonb_build_object(
 'name',l.item_name,'employeeLineId',l.employee_line_id,'quantity',r.quantity,'unit',l.unit)),
 '[]'::jsonb) into payload
 from mir_core.coordination_routes r
 join mir_core.coordination_lines l on(l.organization_id,l.id)=(r.organization_id,r.coordination_line_id)
 where l.organization_id=org and l.coordination_id=o.id and r.route='warehouse';
 payload:=jsonb_build_object('lines',payload,'job',o.job,'address',o.delivery_address,'team',o.team);
 new_revision:=o.revision+1;
 update mir_core.coordination_orders set shipped_at=now(),shipped_by=auth.uid(),
 revision=new_revision,updated_at=now() where organization_id=org and id=o.id;
 insert into mir_core.coordination_shipments(organization_id,coordination_id,revision,shipped_by,payload)
 values(org,o.id,new_revision,auth.uid(),payload);
 insert into mir_core.coordination_events(organization_id,coordination_id,revision,event_type,payload,actor_id)
 values(org,o.id,new_revision,'warehouse_shipped',payload,auth.uid());
 result:=jsonb_build_object('id',o.id,'revision',new_revision,'warehouseStatus','shipped',
  'overallStatus','external_if_pending','stockDeductedAtScan',true);
 return mir_core.coordination_receipt(org,request_id,'ship',
  jsonb_build_object('coordId',coord_id,'expectedRevision',expected_revision),result);
end$function$

CREATE OR REPLACE FUNCTION public.mir_coordination_supplier_po(org uuid, coord_id uuid, route_id uuid, po_id uuid, expected_revision integer, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare o mir_core.coordination_orders;r mir_core.coordination_routes;
 l mir_core.coordination_lines;src mir_core.order_lines;
 po mir_core.orders;po_line uuid;new_po boolean:=false;
 payload jsonb;prior jsonb;result jsonb;rev integer;begin
 if not mir_core.coordination_allowed(org) then raise exception 'Adjointe MIR requise' using errcode='42501';end if;
 payload:=jsonb_build_object('coord',coord_id,'route',route_id,'po',po_id,'expectedRevision',expected_revision);
 prior:=mir_core.coordination_replay(org,request_id,'supplier_po',payload);if prior is not null then return prior;end if;
 select * into o from mir_core.coordination_orders where organization_id=org and id=coord_id for update;
 if not found then raise exception 'Commande inconnue' using errcode='22023';end if;
 if o.revision<>expected_revision then raise exception 'Commande modifiée : actualiser' using errcode='40001';end if;
 select * into r from mir_core.coordination_routes where organization_id=org and id=route_id for update;
 select * into l from mir_core.coordination_lines where organization_id=org and id=r.coordination_line_id and coordination_id=o.id;
 if not found or r.route<>'supplier' then raise exception 'Répartition fournisseur introuvable' using errcode='22023';end if;
 if r.supplier_order_id is not null then raise exception 'Bon déjà associé à cette quantité' using errcode='40001';end if;
 if po_id is null then
  insert into mir_core.orders(organization_id,kind,owner_id,supplier_id)
  values(org,'supplier',auth.uid(),r.supplier_id) returning * into po;
  insert into mir_core.order_revisions(organization_id,order_id,revision,snapshot,created_by)
  values(org,po.id,1,jsonb_build_object('sourceEmployeeOrderId',o.employee_order_id,
   'coordinationId',o.id,'job',o.job,'address',o.delivery_address,'team',o.team,
   'poNumber','MIR-'||to_char(now(),'YYYYMMDD')||'-'||upper(substr(po.id::text,1,6)),
   'status','draft','needsSupplierConfirmation',true),auth.uid());
  new_po:=true;
 else
  select * into po from mir_core.orders where organization_id=org and id=po_id for update;
  if not found or po.kind<>'supplier' or po.supplier_id<>r.supplier_id or po.status<>'draft' then
   raise exception 'Bon existant fermé ou fournisseur différent' using errcode='22023';end if;
 end if;
 select * into src from mir_core.order_lines where organization_id=org and id=l.employee_line_id;
 if not found then raise exception 'Ligne d origine introuvable' using errcode='22023';end if;
 insert into mir_core.order_lines(organization_id,order_id,revision,quantity,unit,specification,model_id,model_version)
 values(org,po.id,po.revision,r.quantity,l.unit,src.specification||
  jsonb_build_object('sourceEmployeeOrderId',o.employee_order_id,'coordinationOrderId',o.id,
   'coordinationRouteId',r.id,'job',o.job,'address',o.delivery_address,'needsProductionReview',true),
  src.model_id,src.model_version) returning id into po_line;
 update mir_core.coordination_routes set supplier_order_id=po.id,supplier_line_id=po_line,
 production_status='ordered' where organization_id=org and id=r.id;
 rev:=o.revision+1;update mir_core.coordination_orders set revision=rev,updated_at=now()
 where organization_id=org and id=o.id;
 insert into mir_core.coordination_events(organization_id,coordination_id,revision,event_type,payload,actor_id)
 values(org,o.id,rev,'po_linked',jsonb_build_object('supplierId',r.supplier_id,'poId',po.id,
  'poLineId',po_line,'lineId',l.id,'quantity',r.quantity),auth.uid());
 result:=jsonb_build_object('revision',rev,'supplierOrderId',po.id,'supplierLineId',po_line,
  'created',new_po,'status','draft','sent',false);
 return mir_core.coordination_receipt(org,request_id,'supplier_po',payload,result);
end$function$

CREATE OR REPLACE FUNCTION public.mir_coordination_supplier_receive(org uuid, coord_id uuid, route_id uuid, quantity numeric, expected_revision integer, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare o mir_core.coordination_orders;r mir_core.coordination_routes;
 l mir_core.coordination_lines;rev integer;payload jsonb;prior jsonb;result jsonb;begin
 if not mir_core.coordination_allowed(org) then raise exception 'Adjointe MIR requise' using errcode='42501';end if;
 payload:=jsonb_build_object('coord',coord_id,'route',route_id,'quantity',quantity,'expectedRevision',expected_revision);
 prior:=mir_core.coordination_replay(org,request_id,'supplier_receive',payload);if prior is not null then return prior;end if;
 select * into o from mir_core.coordination_orders where organization_id=org and id=coord_id for update;
 if not found then raise exception 'Commande introuvable' using errcode='22023';end if;
 if o.revision<>expected_revision then raise exception 'Commande modifiée : actualiser' using errcode='40001';end if;
 select * into r from mir_core.coordination_routes where organization_id=org and id=route_id for update;
 select * into l from mir_core.coordination_lines where organization_id=org and id=r.coordination_line_id and coordination_id=o.id;
 if not found or r.route<>'supplier' or r.supplier_order_id is null then raise exception 'Bon fournisseur inexistant' using errcode='22023';end if;
 if quantity is null or quantity<=0 or scale(quantity)>3 or r.received_qty+quantity>r.quantity
 then raise exception 'Réception supérieure à la quantité fournisseur' using errcode='22023';end if;
 update mir_core.coordination_routes set received_qty=coordination_routes.received_qty+mir_coordination_supplier_receive.quantity,
 production_status=case when coordination_routes.received_qty+mir_coordination_supplier_receive.quantity=coordination_routes.quantity
 then 'received' else 'received_partial' end where organization_id=org and id=r.id;
 rev:=o.revision+1;update mir_core.coordination_orders set revision=rev,updated_at=now() where organization_id=org and id=o.id;
 insert into mir_core.coordination_events(organization_id,coordination_id,revision,event_type,payload,actor_id)
 values(org,o.id,rev,'supplier_received',jsonb_build_object('supplierId',r.supplier_id,'poId',r.supplier_order_id,
  'lineId',l.id,'receivedQty',quantity,'totalReceived',r.received_qty+quantity),auth.uid());
 result:=jsonb_build_object('revision',rev,'receivedQty',r.received_qty+quantity,
  'remainingQty',r.quantity-r.received_qty-quantity);
 return mir_core.coordination_receipt(org,request_id,'supplier_receive',payload,result);
end$function$

CREATE OR REPLACE FUNCTION public.mir_coordination_supplier_status(org uuid, coord_id uuid, route_id uuid, next_status text, expected_revision integer, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare o mir_core.coordination_orders;route_row mir_core.coordination_routes;
 line_row mir_core.coordination_lines;prior jsonb;payload jsonb;result jsonb;rev integer;
 old_rank integer;new_rank integer;begin
 if not mir_core.coordination_allowed(org) then raise exception 'Adjointe MIR requise' using errcode='42501';end if;
 if next_status not in ('ordered','in_production','ready') or next_status is null then
  raise exception 'État de fabrication inconnu' using errcode='22023';end if;
 payload:=jsonb_build_object('coord',coord_id,'route',route_id,'state',next_status,'expectedRevision',expected_revision);
 prior:=mir_core.coordination_replay(org,request_id,'supplier_status',payload);if prior is not null then return prior;end if;
 select * into o from mir_core.coordination_orders where organization_id=org and id=coord_id for update;
 if not found then raise exception 'Commande inconnue' using errcode='22023';end if;
 if o.revision<>expected_revision then raise exception 'Révision modifiée : actualiser' using errcode='40001';end if;
 select * into route_row from mir_core.coordination_routes where organization_id=org and id=route_id for update;
 if not found or route_row.route<>'supplier' or route_row.supplier_order_id is null then
  raise exception 'Bon fournisseur requis' using errcode='22023';end if;
 select * into line_row from mir_core.coordination_lines where organization_id=org
 and id=route_row.coordination_line_id and coordination_id=o.id;
 if not found then raise exception 'Ligne fournisseur hors commande' using errcode='22023';end if;
 if route_row.received_qty>0 then
  raise exception 'Réception déjà commencée : état fondé sur les quantités réellement reçues' using errcode='40001';end if;
 old_rank:=case route_row.production_status when 'to_order' then 0 when 'ordered' then 1 when 'in_production' then 2 when 'ready' then 3 else 4 end;
 new_rank:=case next_status when 'ordered' then 1 when 'in_production' then 2 else 3 end;
 if new_rank<old_rank then raise exception 'Impossible de revenir en arrière sans révision explicite' using errcode='40001';end if;
 rev:=o.revision+1;
 update mir_core.coordination_routes set production_status=next_status where organization_id=org and id=route_id;
 update mir_core.coordination_orders set revision=rev,updated_at=now() where organization_id=org and id=o.id;
 insert into mir_core.coordination_events(organization_id,coordination_id,revision,event_type,payload,actor_id)
 values(org,o.id,rev,'supplier_status',jsonb_build_object('routeId',route_id,'poId',route_row.supplier_order_id,
 'previous',route_row.production_status,'status',next_status,'name',line_row.item_name),auth.uid());
 result:=jsonb_build_object('revision',rev,'state',next_status,'supplierOrderId',route_row.supplier_order_id);
 return mir_core.coordination_receipt(org,request_id,'supplier_status',payload,result);
end$function$

