 elsif action='start_delivery' then select * into run from mir_core.delivery_runs where organization_id=org and id=entity and driver_id=auth.uid() and status='ready' for update;if not found then raise exception 'Départ non autorisé' using errcode='42501';end if;
  if exists(select 1 from mir_core.inspection_rules x where x.organization_id=org and x.phase='pre_departure' and x.active and x.requirement='required' and(x.vehicle_id is null or x.vehicle_id=run.vehicle_id) and(x.vehicle_type is null or x.vehicle_type=(select vehicle_type from mir_core.vehicles where organization_id=org and id=run.vehicle_id)) and(not x.trailer_only or run.trailer_id is not null) and not exists(select 1 from mir_core.run_inspections i join mir_core.inspection_results z on(z.organization_id,z.inspection_id)=(i.organization_id,i.id) where i.organization_id=org and i.run_id=run.id and i.phase='pre_departure' and z.rule_id=x.id and z.result in('conform','na'))) then raise exception 'Vérifications obligatoires incomplètes' using errcode='42501';end if;
  if exists(select 1 from mir_core.run_inspections i join mir_core.inspection_results z on(z.organization_id,z.inspection_id)=(i.organization_id,i.id) join mir_core.inspection_rules x on(x.organization_id,x.id)=(z.organization_id,z.rule_id) where i.organization_id=org and i.run_id=run.id and z.result='problem' and x.failure_blocks and not exists(select 1 from mir_core.delivery_approvals a where a.organization_id=org and a.run_id=run.id and a.rule_id=x.id and a.status='approved')) then raise exception 'Départ bloqué: approbation requise' using errcode='42501';end if;
  update mir_core.delivery_runs set status='en_route',departed_at=now() where organization_id=org and id=run.id;update mir_core.vehicles set status='delivering' where organization_id=org and id=run.vehicle_id;
 elsif action='arrive' then update mir_core.delivery_runs set status='arrived',arrived_at=now() where organization_id=org and id=entity and driver_id=auth.uid() and status='en_route' returning * into run;if not found then raise exception 'Arrivée non autorisée' using errcode='42501';end if;update mir_core.vehicles set status='at_job' where organization_id=org and id=run.vehicle_id;
 elsif action='deliver_item' then select * into run from mir_core.delivery_runs where organization_id=org and id=entity and driver_id=auth.uid() and status in('arrived','partial') for update;if not found then raise exception 'Livraison non autorisée' using errcode='42501';end if;q:=(payload->>'quantity')::numeric;item:=payload->>'itemKey';select id into loc_from from mir_core.inventory_locations where organization_id=org and vehicle_id=run.vehicle_id;select id into loc_to from mir_core.inventory_locations where organization_id=org and job_id=(payload->>'jobId')::uuid;if loc_to is null then insert into mir_core.inventory_locations(organization_id,location_type,name,job_id) values(org,'job','Chantier '||(payload->>'jobId'),(payload->>'jobId')::uuid) returning id into loc_to;end if;insert into mir_core.inventory_transfers(organization_id,item_key,item_name,quantity,from_location,to_location,run_id,order_id,job_id,vehicle_id,employee_id,reason,client_request_id) values(org,item,coalesce(payload->>'itemName',item),q,loc_from,loc_to,run.id,nullif(payload->>'orderId','')::uuid,(payload->>'jobId')::uuid,run.vehicle_id,auth.uid(),'deliver',request_id);update mir_core.delivery_load_items set delivered_qty=delivered_qty+q,updated_at=now() where organization_id=org and run_id=run.id and item_key=item and delivered_qty+returned_qty+damaged_qty+q<=loaded_qty;if not found then raise exception 'Quantité supérieure au chargement' using errcode='22023';end if;
 elsif action='delivery_proof' then select * into run from mir_core.delivery_runs where organization_id=org and id=entity and driver_id=auth.uid() and status in('arrived','partial') for update;if not found then raise exception 'Preuve non autorisée' using errcode='42501';end if;insert into mir_core.delivery_proofs(organization_id,run_id,job_id,outcome,recipient_name,signature_path,photo_path,position,comment,received_by,created_by) values(org,run.id,(payload->>'jobId')::uuid,payload->>'outcome',nullif(payload->>'recipientName',''),nullif(payload->>'signaturePath',''),nullif(payload->>'photoPath',''),payload->'position',coalesce(payload->>'comment',''),nullif(payload->>'receivedBy','')::uuid,auth.uid());update mir_core.delivery_runs set status=case when payload->>'outcome'='delivered' then 'delivered' else 'partial' end where organization_id=org and id=run.id;
 elsif action='return_item' then select * into run from mir_core.delivery_runs where organization_id=org and id=entity and driver_id=auth.uid() and status in('partial','delivered','returning','arrived') for update;if not found then raise exception 'Retour non autorisé' using errcode='42501';end if;q:=(payload->>'quantity')::numeric;item:=payload->>'itemKey';select id into loc_from from mir_core.inventory_locations where organization_id=org and vehicle_id=run.vehicle_id;select id into loc_to from mir_core.inventory_locations where organization_id=org and location_type=case when coalesce((payload->>'damaged')::boolean,false) then 'quarantine' else 'return' end;insert into mir_core.inventory_transfers(organization_id,item_key,item_name,quantity,from_location,to_location,run_id,vehicle_id,employee_id,reason,client_request_id) values(org,item,coalesce(payload->>'itemName',item),q,loc_from,loc_to,run.id,run.vehicle_id,auth.uid(),case when coalesce((payload->>'damaged')::boolean,false) then 'damage' else 'return' end,request_id);update mir_core.delivery_load_items set returned_qty=returned_qty+case when coalesce((payload->>'damaged')::boolean,false) then 0 else q end,damaged_qty=damaged_qty+case when coalesce((payload->>'damaged')::boolean,false) then q else 0 end where organization_id=org and run_id=run.id and item_key=item and delivered_qty+returned_qty+damaged_qty+q<=loaded_qty;
 elsif action='finish_run' then update mir_core.delivery_runs set status='completed',completed_at=now(),end_odometer=nullif(payload->>'odometer','')::numeric,gps_enabled=false,last_position=null where organization_id=org and id=entity and driver_id=auth.uid() and status in('partial','delivered','returning') returning * into run;if not found then raise exception 'Fin de tournée non autorisée' using errcode='42501';end if;update mir_core.vehicles set status='available',current_odometer=greatest(current_odometer,coalesce(run.end_odometer,current_odometer)) where organization_id=org and id=run.vehicle_id;
 elsif action='approval_request' then insert into mir_core.delivery_approvals(organization_id,run_id,inspection_id,rule_id,requested_by,reason) values(org,entity,nullif(payload->>'inspectionId','')::uuid,nullif(payload->>'ruleId','')::uuid,auth.uid(),btrim(payload->>'reason')) returning id into transfer;
 elsif action='approval_decide' then if r not in('boss','admin') or payload->>'decision' not in('approved','refused') or length(btrim(coalesce(payload->>'reason','')))=0 then raise exception 'Boss ou Admin requis' using errcode='42501';end if;update mir_core.delivery_approvals set status=payload->>'decision',decided_by=auth.uid(),decision_reason=btrim(payload->>'reason'),decided_at=now() where organization_id=org and id=entity and status='pending';
 else raise exception 'Action logistique inconnue' using errcode='22023';end if;
 insert into mir_core.logistics_audit(organization_id,actor_id,action,entity_type,entity_id,details) values(org,auth.uid(),action,'delivery_run',coalesce(run.id,entity),payload);
 return jsonb_build_object('ok',true,'id',coalesce(run.id,transfer,entity));
end$function$

CREATE OR REPLACE FUNCTION public.mir_management_action(org uuid, action text, entity uuid DEFAULT NULL::uuid, payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$declare r text:=mir_core.staff_role(org);result uuid;old jsonb;amt numeric;begin
 if r not in('assistant','boss','admin') then raise exception 'Accès gestion refusé' using errcode='42501';end if;
 if action='dashboard_save' then delete from dashboard_preferences where organization_id=org and user_id=auth.uid();insert into dashboard_preferences(organization_id,user_id,block_key,position,visible,collapsed,max_items) select org,auth.uid(),x->>'key',coalesce((x->>'position')::int,0),coalesce((x->>'visible')::boolean,true),coalesce((x->>'collapsed')::boolean,false),coalesce((x->>'maxItems')::int,5) from jsonb_array_elements(coalesce(payload->'blocks','[]')) x;return jsonb_build_object('ok',true);end if;
 if action='estimate_decide' then if r not in('boss','admin') then raise exception 'Boss requis' using errcode='42501';end if;select to_jsonb(e) into old from estimates e where organization_id=org and id=entity for update;if old is null then raise exception 'Soumission introuvable';end if;update estimates set status=case payload->>'decision' when 'approved' then 'approved' when 'refused' then 'refused' else 'review' end,approved_by=case when payload->>'decision'='approved' then auth.uid() end,approved_at=case when payload->>'decision'='approved' then now() end,updated_at=now() where organization_id=org and id=entity;
 elsif action='estimate_submit' then update estimates set status='boss_approval',updated_at=now() where organization_id=org and id=entity and status in('draft','incomplete','review');if not found then raise exception 'Soumission non modifiable';end if;
 elsif action='estimate_new_version' then select to_jsonb(e) into old from estimates e where organization_id=org and id=entity for update;if old is null or old->>'status' not in('sent','viewed','change_requested','accepted') then raise exception 'Version envoyée requise';end if;insert into estimate_versions select org,entity,(old->>'current_version')::int,'archived',old,payload->>'reason',now(),auth.uid(),now();update estimates set current_version=current_version+1,status='draft',updated_at=now() where organization_id=org and id=entity;
 elsif action='payment_record' then if not mir_core.management_allowed(org,'payments_record') then raise exception 'Permission paiement requise' using errcode='42501';end if;amt:=(payload->>'amount')::numeric;select to_jsonb(i) into old from invoices i where organization_id=org and id=entity for update;insert into invoice_payments(organization_id,invoice_id,amount,method,note,recorded_by) values(org,entity,amt,coalesce(payload->>'method',''),coalesce(payload->>'note',''),auth.uid()) returning id into result;update invoices set paid_amount=least(total,paid_amount+amt),status=case when paid_amount+amt>=total then 'paid' else 'partial' end,updated_at=now() where organization_id=org and id=entity;
 else raise exception 'Action inconnue';end if;
 insert into management_audit(organization_id,actor_id,action,entity_type,entity_id,previous_data,new_data,reason) values(org,auth.uid(),action,split_part(action,'_',1),entity,old,payload,coalesce(payload->>'reason',''));return jsonb_build_object('ok',true,'id',result);
end$function$

CREATE OR REPLACE FUNCTION public.mir_message_ack(org uuid, message uuid, state text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$declare row mir_core.message_receipts;begin
 if state not in ('delivered','read') then raise exception 'Accusé invalide' using errcode='22023';end if;
 update mir_core.message_receipts set delivered_at=coalesce(delivered_at,now()),read_at=case when state='read' then coalesce(read_at,now()) else read_at end where organization_id=org and message_id=message and user_id=auth.uid() returning * into row;
 if not found then raise exception 'Message non autorisé' using errcode='42501';end if;
 return jsonb_build_object('deliveredAt',row.delivered_at,'readAt',row.read_at);
end$function$

CREATE OR REPLACE FUNCTION public.mir_message_send(org uuid, conversation uuid, body text, job uuid, plan uuid, attachment text, request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$declare result uuid;recipient uuid;begin
 if not mir_core.conversation_allowed(org,conversation) then raise exception 'Conversation non autorisée' using errcode='42501';end if;
 if request_id is null or length(btrim(body)) not between 1 and 4000 or (job is not null and not mir_core.job_allowed(org,job)) then raise exception 'Message invalide' using errcode='22023';end if;
 select id into result from mir_core.messages where organization_id=org and sender_id=auth.uid() and client_request_id=request_id;
 if found then return jsonb_build_object('id',result,'state','sent','sentAt',(select sent_at from mir_core.messages where organization_id=org and id=result));end if;
 insert into mir_core.messages(organization_id,conversation_id,sender_id,client_request_id,body,job_id,plan_document_id,attachment_path)
 values(org,conversation,auth.uid(),request_id,btrim(body),job,plan,nullif(btrim(attachment),'')) on conflict(organization_id,sender_id,client_request_id) do nothing;
 select id into result from mir_core.messages where organization_id=org and sender_id=auth.uid() and client_request_id=request_id;
 for recipient in select user_id from mir_core.conversation_participants where organization_id=org and conversation_id=conversation and active and user_id<>auth.uid() loop
  insert into mir_core.message_receipts(organization_id,message_id,user_id) values(org,result,recipient) on conflict do nothing;
  insert into mir_core.notifications(organization_id,user_id,kind,title,route,entity_id) values(org,recipient,'message','Nouveau message',jsonb_build_object('view','messages','conversationId',conversation),result);
 end loop;
 return jsonb_build_object('id',result,'state','sent','sentAt',(select sent_at from mir_core.messages where organization_id=org and id=result));
end$function$

CREATE OR REPLACE FUNCTION public.mir_portal_accept_invitation(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare identity jsonb;uid uuid;inv mir_core.account_invitations;jid uuid;begin
 identity:=mir_core.account_identity();uid:=(identity->>'id')::uuid;
 if p_token is null or p_token!~'^[A-Za-z0-9_-]{43}$' then raise exception 'Invitation invalide' using errcode='42501';end if;
 select * into inv from mir_core.account_invitations where token_hash=encode(sha256(convert_to(p_token,'UTF8')),'hex') for update;
 if not found or inv.revoked_at is not null or inv.expires_at<=now() or lower(identity->>'email')<>inv.email or (inv.accepted_by is not null and inv.accepted_by<>uid) then raise exception 'Invitation expirée, déjà utilisée ou destinée à une autre adresse' using errcode='42501',detail='INVITATION_INVALID';end if;
 if inv.accepted_by=uid then return jsonb_build_object('ok',true,'alreadyAccepted',true);end if;
 insert into mir_core.memberships(organization_id,user_id,role,active) values(inv.organization_id,uid,'employee',true)
 on conflict(organization_id,user_id) do update set role=case when memberships.role='admin' then 'admin' else 'employee' end,active=true;
 foreach jid in array inv.job_ids loop
  insert into mir_core.job_memberships(organization_id,job_id,user_id) values(inv.organization_id,jid,uid) on conflict do nothing;
 end loop;
 update mir_core.account_invitations set accepted_by=uid,accepted_at=now() where id=inv.id;
 return jsonb_build_object('ok',true);
end $function$

CREATE OR REPLACE FUNCTION public.mir_portal_command(p_request_id uuid, p_command text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$declare account jsonb;org uuid;member uuid;ids uuid[];result jsonb;scalar uuid;begin
 account:=public.mir_account_snapshot();org:=(account->>'organizationId')::uuid;
 if account->>'role' not in ('employee','admin') or p_request_id is null or jsonb_typeof(p_payload)<>'object' then raise exception 'Action interne invalide' using errcode='42501';end if;
 if p_command='ASSIGN_MEMBER_JOBS' then
  if account->>'role'<>'admin' then raise exception 'Admin requis' using errcode='42501';end if;member:=(p_payload->>'memberId')::uuid;
  if not exists(select 1 from mir_core.memberships where organization_id=org and user_id=member and active and role='employee') then raise exception 'Employé actif requis' using errcode='42501';end if;
  select coalesce(array_agg(distinct value::uuid),'{}') into ids from jsonb_array_elements_text(p_payload->'jobIds');
  if exists(select 1 from unnest(ids) id where not exists(select 1 from mir_core.jobs j where j.organization_id=org and j.id=id and not j.archived)) then raise exception 'Chantier inaccessible' using errcode='42501';end if;
  perform 1 from mir_core.memberships where organization_id=org and user_id=member for update;delete from mir_core.job_memberships where organization_id=org and user_id=member and not(job_id=any(ids));insert into mir_core.job_memberships select org,id,member from unnest(ids) id on conflict do nothing;result:=jsonb_build_object('ok',true);
 elsif p_command='EXTRA_SUBMIT' then scalar:=public.mir_extra_submit(org,(p_payload->>'jobId')::uuid,p_payload->>'description',p_payload->>'photoPath',nullif(p_payload->>'dueAt','')::timestamptz,p_request_id);result:=jsonb_build_object('id',scalar);
 elsif p_command='DELIVERY_ISSUE' then scalar:=public.mir_delivery_issue(org,(p_payload->>'jobId')::uuid,nullif(p_payload->>'orderId','')::uuid,nullif(p_payload->>'lineId','')::uuid,nullif(p_payload->>'supplierOrderId','')::uuid,p_payload->>'comment',p_payload->>'photoPath',p_request_id);result:=jsonb_build_object('id',scalar);
 elsif p_command='DELIVERY_RECEIVE' then result:=public.mir_delivery_receive(org,(p_payload->>'jobId')::uuid,(p_payload->>'orderId')::uuid,(p_payload->>'lineId')::uuid,(p_payload->>'quantity')::numeric,p_payload->>'place',p_payload->>'photoPath',p_request_id);
 elsif p_command='HR_SUBMIT' then scalar:=public.mir_hr_submit(org,p_payload->>'kind',(p_payload->>'start')::date,(p_payload->>'end')::date,p_payload->>'note',p_request_id);result:=jsonb_build_object('id',scalar);
 elsif p_command='MESSAGE_SEND' then result:=public.mir_message_send(org,(p_payload->>'conversationId')::uuid,p_payload->>'body',nullif(p_payload->>'jobId','')::uuid,nullif(p_payload->>'planDocumentId','')::uuid,p_payload->>'attachmentPath',p_request_id);
 elsif p_command='MESSAGE_ACK' then result:=public.mir_message_ack(org,(p_payload->>'messageId')::uuid,p_payload->>'state');
 elsif p_command='NOTIFICATION_READ' then result:=jsonb_build_object('ok',public.mir_notification_read(org,(p_payload->>'notificationId')::uuid));
 else raise exception 'Cette action n est pas raccordée au portail' using errcode='0A000';end if;
 return jsonb_build_object('result',result,'snapshot',public.mir_portal_snapshot());
end$function$

CREATE OR REPLACE FUNCTION public.mir_portal_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare account jsonb;org uuid;uid uuid;shared jsonb;members jsonb;catalogue jsonb;jobs jsonb;begin
 account:=public.mir_account_snapshot();org:=(account->>'organizationId')::uuid;uid:=(account->>'userId')::uuid;
 if account->>'role' not in ('employee','admin') then raise exception 'Accès équipe MIR requis' using errcode='42501',detail='ACCESS_DENIED';end if;
 shared:=public.mir_shared_snapshot(org);
 select coalesce(jsonb_agg(jsonb_build_object('id',m.user_id,'name',coalesce(u.raw_user_meta_data->>'full_name',u.email),'email',u.email,'role',m.role,'active',m.active)),'[]') into members
 from mir_core.memberships m join auth.users u on u.id=m.user_id where m.organization_id=org and (account->>'role'='admin' or m.user_id=uid);
 select coalesce(jsonb_agg(c.specification||jsonb_build_object('id',c.id,'name',c.name,'active',true)),'[]') into catalogue from mir_core.catalogue_items c where c.organization_id=org and c.channel='store' and c.published and not c.archived;
 select coalesce(jsonb_agg(j||jsonb_build_object('assignedMemberIds',(select coalesce(jsonb_agg(jm.user_id),'[]') from mir_core.job_memberships jm where jm.organization_id=org and jm.job_id=(j->>'id')::uuid and (account->>'role'='admin' or jm.user_id=uid)))),'[]') into jobs from jsonb_array_elements(shared->'jobs') j;
 return jsonb_build_object('mode','connected','demo',false,'actorId',uid,'members',members,'jobs',jobs,'planVersions','[]'::jsonb,'catalogue',catalogue,
 'orders','[]'::jsonb,'sharedOrders',shared->'orders','deliveries','[]'::jsonb,'movements','[]'::jsonb,'inventory','{}'::jsonb,'favorites','{}'::jsonb,
 'capabilities',jsonb_build_object('documents',false,'checkout',false));
end $function$

CREATE OR REPLACE FUNCTION public.mir_submit_request(org uuid, request_id uuid, model uuid, publication_revision integer, configuration jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare actor_role text;p mir_core.model_publications;prior mir_core.request_keys;oid uuid;
 spec jsonb;payload jsonb;quantity integer;metal text;price bigint;field record;
 tariff jsonb; delivery jsonb; delivery_address mir_core.customer_addresses; distance numeric; fixed_cents bigint;begin
 select role into actor_role from mir_core.memberships where organization_id=org and user_id=auth.uid() and active;
 if actor_role not in ('client','employee') or actor_role is null then raise exception 'Compte client ou employé actif requis' using errcode='42501';end if;
 payload:=jsonb_build_object('model',model,'revision',publication_revision,'configuration',configuration);
 perform pg_advisory_xact_lock(hashtextextended(org::text||auth.uid()::text||request_id::text,0));
 select * into prior from mir_core.request_keys k where k.organization_id=org and k.user_id=auth.uid() and k.request_id=mir_submit_request.request_id;
 if found then
 if prior.payload is distinct from payload then raise exception 'Référence utilisée avec un autre contenu' using errcode='22023';end if;
 return prior.order_id;end if;
 select * into p from mir_core.model_publications where organization_id=org and model_id=model for share;
 if not found or p.archived or p.revision<>publication_revision or
 not(case actor_role when 'client' then p.boutique else p.store end) then raise exception 'Publication indisponible ou modifiée' using errcode='40001';end if;
 if exists(select 1 from mir_core.models where organization_id=org and id=model and archived) then raise exception 'Modèle archivé';end if;
 select specification into spec from mir_core.model_versions where organization_id=org and model_id=model and version=p.version;
 if jsonb_typeof(configuration) is distinct from 'object' or octet_length(configuration::text)>65536 then raise exception 'Configuration invalide';end if;
 quantity:=(configuration->>'quantity')::integer;metal:=configuration->>'metal';
 if quantity is null or quantity<1 or quantity>10000 or metal not in ('aluminium','acier') or metal is null then raise exception 'Quantité ou métal invalide';end if;
 if jsonb_typeof(coalesce(p.configuration_rules->'materials',spec->'allowed'->'materials'))='array' and not (coalesce(p.configuration_rules->'materials',spec->'allowed'->'materials') @> jsonb_build_array(metal)) then raise exception 'Métal non proposé pour ce modèle';end if;
 -- No client price, stock, role, owner or geometry is accepted as authoritative.
 if configuration - array['quantity','metal','color','measures','chantier','note','tariffRevision','deliveryAddressId','deliveryAddressVersion','deliveryFeeCents'] <> '{}'::jsonb then raise exception 'Champs non autorisés';end if;
 if jsonb_typeof(configuration->'measures') is distinct from 'object' then raise exception 'Mesures requises';end if;
 for field in select * from jsonb_each(p.locked_measures) loop
 if configuration->'measures'->field.key is distinct from field.value then raise exception 'Mesure verrouillée : %',field.key;end if;
 end loop;
 if configuration->'measures'->>'length' is distinct from p.sale_length_in::text then raise exception 'Longueur de vente non autorisée';end if;
 if coalesce(btrim(configuration->>'color'),'')='' or length(configuration->>'color')>200 then raise exception 'Couleur requise';end if;
 if jsonb_array_length(coalesce(p.configuration_rules->'colors','[]'))>0 and not(p.configuration_rules->'colors' @> jsonb_build_array(configuration->>'color')) then raise exception 'Couleur non proposée' using errcode='22023';end if;
 if p.configuration_rules ? 'color_edit_roles' and not(p.configuration_rules->'color_edit_roles' @> jsonb_build_array(actor_role)) and configuration->>'color' is distinct from p.configuration_rules->>'fixed_color' then raise exception 'Couleur verrouillée' using errcode='42501';end if;
 if p.configuration_rules ? 'measure_edit_roles' and not(p.configuration_rules->'measure_edit_roles' @> jsonb_build_array(actor_role)) and (configuration->'measures')-'length' is distinct from (p.standard_measures||p.locked_measures)-'length' then raise exception 'Mesures réservées à un autre rôle' using errcode='42501';end if;
 if actor_role='employee' and not exists(select 1 from mir_core.jobs j join mir_core.job_memberships a on(a.organization_id,a.job_id)=(j.organization_id,j.id) where j.organization_id=org and j.id::text=configuration->>'chantier' and not j.archived and a.user_id=auth.uid()) then raise exception 'Chantier non affecté' using errcode='42501';end if;
 if actor_role='client' then
  perform pg_advisory_xact_lock_shared(hashtextextended('boutique-bend-tariff:'||org::text,0));
  tariff:=mir_core.boutique_bend_tariff(org);
  if coalesce(configuration->>'tariffRevision','0') is distinct from tariff->>'revision' then
   raise exception 'Les tarifs ont changé. Vérifiez le nouveau prix.' using errcode='PT409';
  end if;
  fixed_cents:=case metal when 'aluminium' then p.aluminum_cents else p.steel_cents end;
  price:=mir_core.boutique_bend_price(spec,configuration->'measures',metal,fixed_cents,tariff);
  if configuration ? 'deliveryAddressId' then
   select * into delivery_address from mir_core.customer_addresses a
     where a.id=(configuration->>'deliveryAddressId')::uuid and a.user_id=auth.uid() for share;
   if not found or delivery_address.updated_at::text is distinct from configuration->>'deliveryAddressVersion' then
    raise exception 'Adresse indisponible ou modifiée. Vérifiez la livraison.' using errcode='PT409';
   end if;
   distance:=mir_core.boutique_delivery_km(delivery_address.id,delivery_address.address);
   delivery:=mir_core.boutique_delivery_result(distance,price*quantity,(tariff->>'delivery_cents')::bigint)
     ||jsonb_build_object('address',delivery_address.address);
   if delivery->'feeCents' is distinct from configuration->'deliveryFeeCents' then
    raise exception 'Les frais de livraison ont changé. Vérifiez la livraison.' using errcode='PT409';
   end if;
  end if;
 elsif configuration ? 'deliveryAddressId' or configuration ? 'deliveryAddressVersion' or configuration ? 'deliveryFeeCents' or configuration ? 'tariffRevision' then
  raise exception 'Tarifs et livraison réservés à la Boutique' using errcode='42501';
 end if;
 insert into mir_core.orders(organization_id,kind,owner_id) values(org,actor_role,auth.uid()) returning id into oid;
 insert into mir_core.order_revisions(organization_id,order_id,revision,snapshot) values(org,oid,1,
 jsonb_build_object('modelId',model,'modelVersion',p.version,'publicationRevision',p.revision,'specification',spec,
 'configurationRules',p.configuration_rules,'configuration',configuration,'measureUnit','in','unitPriceCents',price,'totalCents',price*quantity,'currency','CAD','billingLengthIn',case when price is not null then 120 end,
 'tariffRevision',(tariff->>'revision')::integer,'delivery',delivery,'saleLengthIn',p.sale_length_in,'conditions',p.conditions,
 'validation','pending-admin-review','availability','unknown'));
 insert into mir_core.order_events(organization_id,order_id,event_type) values(org,oid,'request-submitted');
 insert into mir_core.request_keys values(org,auth.uid(),request_id,payload,oid);return oid;
end $function$

CREATE OR REPLACE FUNCTION public.mir_team_save(org uuid, team uuid, name text, leader uuid, members uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$declare result uuid:=coalesce(team,gen_random_uuid());m uuid;begin
 if mir_core.staff_role(org) not in ('admin','boss') then raise exception 'Boss ou admin requis' using errcode='42501';end if;
 if length(btrim(name)) not between 1 and 120 or mir_core.staff_role(org,leader)<>'chef_equipe' then raise exception 'Équipe ou chef invalide' using errcode='22023';end if;
 insert into mir_core.teams(organization_id,id,name,leader_id) values(org,result,btrim(name),leader) on conflict(organization_id,id) do update set name=excluded.name,leader_id=excluded.leader_id,active=true;
 delete from mir_core.team_members where organization_id=org and team_id=result;
 foreach m in array coalesce(members,'{}') loop if mir_core.staff_role(org,m) not in ('employe','chef_equipe') then raise exception 'Membre invalide' using errcode='22023';end if;insert into mir_core.team_members values(org,result,m,true,now());end loop;
 insert into mir_core.team_members values(org,result,leader,true,now()) on conflict do nothing;return result;end$function$

CREATE OR REPLACE FUNCTION public.mir_warehouse_grant_access(org uuid, member uuid, allow_access boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
begin
 if not mir_core.has_role(org,array['admin']) then raise exception 'Admin requis' using errcode='42501';end if;
 if member is null or allow_access is null or not exists(
  select 1 from mir_core.memberships m where m.organization_id=org
    and m.user_id=member and m.role='employee' and m.active
 ) then raise exception 'Employé MIR actif requis' using errcode='22023';end if;
 insert into mir_core.warehouse_access(organization_id,user_id,active,granted_by)
 values(org,member,allow_access,auth.uid())
 on conflict(organization_id,user_id) do update set active=excluded.active,
 granted_by=excluded.granted_by,granted_at=now();
 return true;
end$function$

CREATE OR REPLACE FUNCTION public.mir_warehouse_link_order_line(org uuid, line_id uuid, sku_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare ln mir_core.order_lines;item mir_core.warehouse_skus;ord mir_core.orders;
 ref text;begin
 if not mir_core.has_role(org,array['admin']) then raise exception 'Admin requis' using errcode='42501';end if;
 select * into ln from mir_core.order_lines where organization_id=org and id=line_id;
 if not found then raise exception 'Ligne de commande introuvable' using errcode='22023';end if;
 select * into ord from mir_core.orders where organization_id=org and id=ln.order_id;
 if ord.kind<>'employee' or ord.status='cancelled' then raise exception 'Commande employé active requise' using errcode='22023';end if;
 select * into item from mir_core.warehouse_skus where organization_id=org and id=sku_id and not archived;
 if not found then raise exception 'Référence de stock introuvable' using errcode='22023';end if;
 ref:=coalesce(ln.specification->>'stockKey',ln.specification->>'inventoryKey');
 if ref is null or ref<>item.source_ref then raise exception 'SKU/variante différente de la commande' using errcode='22023';end if;
 insert into mir_core.warehouse_fulfillment(organization_id,order_line_id,sku_id)
 values(org,line_id,sku_id) on conflict do nothing;
 if not exists(select 1 from mir_core.warehouse_fulfillment
 where organization_id=org and order_line_id=line_id and warehouse_fulfillment.sku_id=sku_id) then
 raise exception 'Ligne déjà liée à une autre référence' using errcode='40001';end if;
 return true;
end$function$

CREATE OR REPLACE FUNCTION public.mir_warehouse_move(org uuid, qr uuid, line_id uuid, delta numeric, request_id uuid, reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare sku_row mir_core.warehouse_skus;balance mir_core.warehouse_stock;
 fulfil mir_core.warehouse_fulfillment;line_row mir_core.order_lines;ord mir_core.orders;
 prior mir_core.warehouse_movements;kind text;rem numeric;out jsonb; note text;begin
 if not mir_core.warehouse_allowed(org) then raise exception 'Accès Entrepôt requis' using errcode='42501';end if;
 if qr is null or request_id is null or delta is null or delta=0 or abs(delta)>100000 or scale(delta)>3 then
  raise exception 'Mouvement invalide' using errcode='22023';end if;
 note:=btrim(coalesce(reason,''));
 if length(note) not between 3 and 300 then raise exception 'Motif requis' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(org::text||request_id::text,0));
 select * into prior from mir_core.warehouse_movements
  where organization_id=org and warehouse_movements.request_id=mir_warehouse_move.request_id;
 if found then
  if prior.actor_id<>auth.uid() or prior.delta<>delta or
    prior.order_line_id is distinct from line_id or prior.reason<>note or
    not exists(select 1 from mir_core.warehouse_skus p where p.organization_id=org
    and p.id=prior.sku_id and p.qr_token=qr) then
   raise exception 'La requête a déjà servi pour un mouvement différent' using errcode='40001';end if;
  return jsonb_build_object('movementId',prior.id,'stockAfter',prior.stock_after,
    'remainingAfter',prior.remaining_after,'replayed',true);
 end if;
 select * into sku_row from mir_core.warehouse_skus where organization_id=org and qr_token=qr and not archived;
 if not found then raise exception 'QR de stock inconnu' using errcode='22023';end if;
 if abs(delta)/sku_row.quantity_step<>trunc(abs(delta)/sku_row.quantity_step) then
  raise exception 'Format de vente incompatible avec cette quantité' using errcode='22023';end if;
 select * into balance from mir_core.warehouse_stock where organization_id=org and sku_id=sku_row.id for update;
 if not found then raise exception 'Stock non initialisé' using errcode='22023';end if;
 if balance.on_hand+delta<0 then raise exception 'Stock insuffisant' using errcode='22023';end if;
 rem:=null;
 if line_id is not null then
  if delta>=0 then raise exception 'Une livraison est une sortie de stock' using errcode='22023';end if;
  select * into fulfil from mir_core.warehouse_fulfillment where organization_id=org and order_line_id=line_id for update;
  if not found or fulfil.sku_id<>sku_row.id then raise exception 'Ligne non associée à ce QR' using errcode='22023';end if;
  select * into line_row from mir_core.order_lines where organization_id=org and id=line_id;
  select * into ord from mir_core.orders where organization_id=org and id=line_row.order_id;
  if ord.kind<>'employee' or ord.status='cancelled' then raise exception 'Commande non livrable' using errcode='22023';end if;
  rem:=line_row.quantity-fulfil.delivered_qty-fulfil.cancelled_qty;
  if -delta>rem then raise exception 'Quantité supérieure au reliquat' using errcode='22023';end if;
  update mir_core.warehouse_fulfillment set delivered_qty=delivered_qty-delta,updated_at=now()
   where organization_id=org and order_line_id=line_id;
  rem:=rem+delta;kind:='delivery';
 else
  if delta>0 then kind:='receipt';
  else kind:='adjustment';end if;
 end if;
 update mir_core.warehouse_stock set on_hand=on_hand+delta,revision=revision+1,updated_at=now()
   where organization_id=org and sku_id=sku_row.id;
 insert into mir_core.warehouse_movements(organization_id,sku_id,order_line_id,actor_id,request_id,
  delta,reason,kind,stock_before,stock_after,remaining_after)
 values(org,sku_row.id,line_id,auth.uid(),request_id,delta,note,kind,balance.on_hand,balance.on_hand+delta,rem)
 returning id into prior.id;
 return jsonb_build_object('movementId',prior.id,'stockAfter',balance.on_hand+delta,
   'remainingAfter',rem,'replayed',false);
end$function$

CREATE OR REPLACE FUNCTION public.mir_warehouse_register(org uuid, kind text, source_ref text, sku_code text, display_name text, unit_name text, step numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare sku_row mir_core.warehouse_skus;begin
 if not mir_core.has_role(org,array['admin']) then raise exception 'Admin requis' using errcode='42501';end if;
 if kind not in ('hardware','bending') or source_ref is null or length(btrim(source_ref)) not between 1 and 300
  or sku_code is null or sku_code !~ '^[A-Za-z0-9][A-Za-z0-9._-]{1,79}$'
  or display_name is null or length(btrim(display_name)) not between 1 and 180
  or unit_name is null or length(btrim(unit_name)) not between 1 and 40
  or step is null or step<=0 or step>1000 or scale(step)>3 then
  raise exception 'Référence de stock invalide' using errcode='22023';
 end if;
 if kind='bending' and not exists(
   select 1 from mir_core.models m where m.organization_id=org
   and m.id::text=source_ref and not m.archived
 ) then raise exception 'Moulure introuvable dans Mes pliages partagés' using errcode='22023';end if;
 insert into mir_core.warehouse_skus(organization_id,source_kind,source_ref,sku,name,unit,quantity_step)
 values(org,kind,source_ref,sku_code,btrim(display_name),btrim(unit_name),step)
 on conflict on constraint warehouse_skus_organization_id_source_kind_source_ref_key do nothing;
 select * into sku_row from mir_core.warehouse_skus
 where organization_id=org and source_kind=kind and warehouse_skus.source_ref=mir_warehouse_register.source_ref;
 if sku_row.sku<>sku_code or sku_row.name<>btrim(display_name) or sku_row.unit<>btrim(unit_name) or sku_row.quantity_step<>step then
  raise exception 'Référence existante : aucune modification silencieuse de SKU/QR' using errcode='40001';end if;
 insert into mir_core.warehouse_stock(organization_id,sku_id) values(org,sku_row.id) on conflict do nothing;
 return jsonb_build_object('id',sku_row.id,'sku',sku_row.sku,'qrToken',sku_row.qr_token);
end$function$

CREATE OR REPLACE FUNCTION public.mir_warehouse_snapshot(org uuid, qr uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'mir_core'
AS $function$
declare product mir_core.warehouse_skus;stock mir_core.warehouse_stock;pending jsonb;log_rows jsonb;begin
 if not mir_core.warehouse_allowed(org) then raise exception 'Accès Entrepôt requis' using errcode='42501';end if;
 select * into product from mir_core.warehouse_skus where organization_id=org and qr_token=qr and not archived;
 if not found then raise exception 'Code QR inconnu ou article archivé' using errcode='22023';end if;
 select * into stock from mir_core.warehouse_stock where organization_id=org and sku_id=product.id;
 select coalesce(jsonb_agg(jsonb_build_object(
  'orderId',ol.order_id,'lineId',ol.id,'skuId',product.id,'requestedQty',ol.quantity,
  'deliveredQty',f.delivered_qty,'cancelledQty',f.cancelled_qty,
  'remainingQty',ol.quantity-f.delivered_qty-f.cancelled_qty,
  'job',coalesce(r.snapshot->>'job',''),'status',o.status
 ) order by o.created_at desc),'[]'::jsonb) into pending
 from mir_core.warehouse_fulfillment f
 join mir_core.order_lines ol on ol.organization_id=f.organization_id and ol.id=f.order_line_id
 join mir_core.orders o on o.organization_id=ol.organization_id and o.id=ol.order_id
 left join mir_core.order_revisions r on r.organization_id=o.organization_id and r.order_id=o.id and r.revision=o.revision
 where f.organization_id=org and f.sku_id=product.id and ol.quantity>f.delivered_qty+f.cancelled_qty and o.status<>'cancelled';
 select coalesce(jsonb_agg(jsonb_build_object('at',m.created_at,'delta',m.delta,'kind',m.kind,
 'reason',m.reason,'actorId',m.actor_id,'orderLineId',m.order_line_id)
 order by m.created_at desc),'[]'::jsonb) into log_rows
 from (select * from mir_core.warehouse_movements where organization_id=org and sku_id=product.id order by created_at desc limit 40)m;
 return jsonb_build_object(
  'sku',jsonb_build_object('id',product.id,'sku',product.sku,'name',product.name,'unit',product.unit,
    'sourceKind',product.source_kind,'sourceRef',product.source_ref,
    'step',product.quantity_step,'qrToken',product.qr_token,'onHand',coalesce(stock.on_hand,0),'revision',stock.revision),
  'orders',pending,'movements',log_rows
 );
end$function$
